    mockLog(TAG, `consumeEntitlement id=${entitlementId} qty=${quantity}`);
    referenceId = referenceId ?? generateId();
    if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isInteger(quantity)) {
      throw new RundotApiError("UNKNOWN", "quantity must be a positive integer", 0);
    }
