var RpcFilesApi = class {
  constructor(rpcClient) {
    this.rpcClient = rpcClient;
  }
  rpcClient;
  async upload(params) {
    return this.rpcClient.call(
      "H5_FILES_UPLOAD" /* H5_FILES_UPLOAD */,
      params
    );
  }
  async confirmUpload(key, options) {
    return this.rpcClient.call(
      "H5_FILES_CONFIRM_UPLOAD" /* H5_FILES_CONFIRM_UPLOAD */,
      { key, ...options },
      -1
    );
  }
  async batchUpload(params) {
    return this.rpcClient.call(
      "H5_FILES_BATCH_UPLOAD" /* H5_FILES_BATCH_UPLOAD */,
      params
    );
  }
  async batchCopy(params) {
    return this.rpcClient.call(
      "H5_FILES_BATCH_COPY" /* H5_FILES_BATCH_COPY */,
      params,
      -1
    );
  }
  async batchConfirm(keys, options) {
    return this.rpcClient.call(
      "H5_FILES_BATCH_CONFIRM" /* H5_FILES_BATCH_CONFIRM */,
      { keys, ...options }
    );
  }
  async getUrl(params) {
    const result = await this.rpcClient.call(
      "H5_FILES_GET_URL" /* H5_FILES_GET_URL */,
      params
    );
    return result.url;
  }
  async getUrls(params) {
    return this.rpcClient.call(
      "H5_FILES_GET_URLS" /* H5_FILES_GET_URLS */,
      params
    );
  }
  async getMetadata(params) {
    return this.rpcClient.call(
      "H5_FILES_GET_METADATA" /* H5_FILES_GET_METADATA */,
      params
    );
  }
  async exists(params) {
    return this.rpcClient.call(
      "H5_FILES_EXISTS" /* H5_FILES_EXISTS */,
      params
    );
  }
  async batchGetMetadata(params) {
    return this.rpcClient.call(
      "H5_FILES_BATCH_METADATA" /* H5_FILES_BATCH_METADATA */,
      params
    );
  }
  async batchExists(params) {
    return this.rpcClient.call(
      "H5_FILES_BATCH_EXISTS" /* H5_FILES_BATCH_EXISTS */,
      params
    );
  }
  async delete(key) {
    await this.rpcClient.call(
      "H5_FILES_DELETE" /* H5_FILES_DELETE */,
      { key }
    );
  }
  async list(params) {
    return this.rpcClient.call(
      "H5_FILES_LIST" /* H5_FILES_LIST */,
      params ?? {}
    );
  }
  async getQuota() {
    return this.rpcClient.call(
      "H5_FILES_GET_QUOTA" /* H5_FILES_GET_QUOTA */,
      {}
    );
  }
  async hasStorageAvailable(sizeBytes, contentType) {
    const quota = await this.getQuota();
    const cap = contentType === "application/zip" ? quota.maxArchiveBytes : quota.maxFileBytes;
    return quota.availableBytes >= sizeBytes && sizeBytes <= cap;
  }
  async setVisibility(key, visibility) {
    return this.rpcClient.call(
      "H5_FILES_SET_VISIBILITY" /* H5_FILES_SET_VISIBILITY */,
      { key, visibility }
    );
  }
  async transform(params) {
    return this.rpcClient.call(
      "H5_FILES_TRANSFORM" /* H5_FILES_TRANSFORM */,
      params,
      -1
    );
  }
  async exportToCloudinary(params) {
    return this.rpcClient.call(
      "H5_FILES_EXPORT_CLOUDINARY" /* H5_FILES_EXPORT_CLOUDINARY */,
      params,
      -1
    );
  }
  async getCompletedJobs() {
    return this.rpcClient.call(
      "H5_POLL_COMPLETED_JOBS" /* H5_POLL_COMPLETED_JOBS */,
      { type: "files" }
    );
  }
};

